const std = @import("std"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const cmok = @import("sy-clou-mock.zig"); const mirr = @import("sy-mirr-stor.zig"); const audt = @import("sy-mirr-audt.zig"); const quot = @import("sy-mirr-quot.zig"); const outb = @import("sy-clou-outb.zig"); const fail = @import("ru-fail-over.zig");
const allo = std.testing.allocator; const NOWZ: i64 = 1795600000000; const DAYZ: i64 = 86400000;
const Rigg = struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, c1zz: cmok.Mock, c2zz: cmok.Mock, c3zz: cmok.Mock, mems: [3]mirr.Memb, stat: mirr.Dead, fanz: mirr.Fanz,
fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.c1zz = cmok.Mock.init(allo); self.c2zz = cmok.Mock.init(allo); self.c3zz = cmok.Mock.init(allo); self.mems = .{ .{ .name = "b2zz", .store = self.c1zz.store(), .idxz = 0 }, .{ .name = "r2zz", .store = self.c2zz.store(), .idxz = 1 }, .{ .name = "tigr", .store = self.c3zz.store(), .idxz = 2 } }; self.stat = try mirr.deadMake(self.aren.allocator(), 3); self.fanz = .{ .dbzz = &self.dbzz, .iozz = std.testing.io, .nowz = NOWZ, .conf = .{}, .prim = self.mems[0], .mirs = self.mems[1..], .stat = &self.stat }; self.fanz.conf.clou_mirr_enab = true; }
fn down(self: *Rigg) void { self.c1zz.deinit(); self.c2zz.deinit(); self.c3zz.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); }
fn frsh(self: *Rigg) void { @memset(self.stat.dead, false); @memset(self.stat.used, false); @memset(self.stat.paus, false); }
fn scal(self: *Rigg, sqlz: [:0]const u8) !i64 { var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); if (!try stmt.step()) return -1; return stmt.colzIntz(0); }
fn have(mock: *cmok.Mock, key2: []const u8, want: []const u8) bool { const gotz = mock.map.get(key2) orelse return false; return std.mem.eql(u8, gotz, want); } };
test "put and delete reach every vendor with the same bytes, get falls back to a mirror" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); const stoz = mirr.fanzStor(&rig3.fanz); try stoz.put(stoz.ctx2, aren, std.testing.io, "cars/rows.jsonl.gz", "AAAA"); try stoz.put(stoz.ctx2, aren, std.testing.io, "cont/latest.enc", "BBBBBB"); try std.testing.expect(Rigg.have(&rig3.c1zz, "cars/rows.jsonl.gz", "AAAA") and Rigg.have(&rig3.c2zz, "cars/rows.jsonl.gz", "AAAA") and Rigg.have(&rig3.c3zz, "cars/rows.jsonl.gz", "AAAA")); try std.testing.expect(Rigg.have(&rig3.c3zz, "cont/latest.enc", "BBBBBB")); try std.testing.expectEqual(@as(u32, 4), rig3.fanz.sent); try std.testing.expectEqual(@as(u32, 0), rig3.fanz.qued); try std.testing.expectEqual(@as(i64, 2), try quot.opsaGetz(&rig3.dbzz, "tigr", NOWZ)); const lstz = try stoz.list(stoz.ctx2, aren, std.testing.io, "cars/"); try std.testing.expectEqual(@as(usize, 1), lstz.len); rig3.c1zz.stoo = true; try std.testing.expectEqualStrings("AAAA", try stoz.get(stoz.ctx2, aren, std.testing.io, "cars/rows.jsonl.gz")); rig3.c1zz.stoo = false; try stoz.del2(stoz.ctx2, aren, std.testing.io, "cars/rows.jsonl.gz"); try std.testing.expectEqual(@as(usize, 1), rig3.c1zz.map.count() + rig3.c2zz.map.count() + rig3.c3zz.map.count() - 2); }
test "a down mirror never fails the put: queued, skipped for the rest of the run, drained when it is back" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); const stoz = mirr.fanzStor(&rig3.fanz); rig3.c2zz.stoo = true; try stoz.put(stoz.ctx2, aren, std.testing.io, "cont/week-1.enc", "one"); try std.testing.expect(rig3.stat.dead[1] and !rig3.stat.dead[2]); try std.testing.expectEqual(@as(u32, 1), rig3.fanz.qued); try std.testing.expect(Rigg.have(&rig3.c3zz, "cont/week-1.enc", "one")); try std.testing.expect(!Rigg.have(&rig3.c2zz, "cont/week-1.enc", "one")); rig3.c2zz.stoo = false; try stoz.put(stoz.ctx2, aren, std.testing.io, "cont/week-2.enc", "two"); try std.testing.expect(!Rigg.have(&rig3.c2zz, "cont/week-2.enc", "two")); try std.testing.expectEqual(@as(i64, 2), try mirr.fanzLeft(&rig3.fanz)); const drn0 = try mirr.fanzDrai(&rig3.fanz, aren); try std.testing.expectEqual(@as(u32, 0), drn0.done); rig3.frsh(); const drn1 = try mirr.fanzDrai(&rig3.fanz, aren); try std.testing.expectEqual(@as(u32, 2), drn1.done); try std.testing.expectEqual(@as(i64, 0), drn1.left); try std.testing.expect(Rigg.have(&rig3.c2zz, "cont/week-1.enc", "one") and Rigg.have(&rig3.c2zz, "cont/week-2.enc", "two")); }
test "the main vendor failing is the only failure that reaches the caller" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); const stoz = mirr.fanzStor(&rig3.fanz); rig3.c1zz.stoo = true; try std.testing.expectError(error.CloudHttp, stoz.put(stoz.ctx2, aren, std.testing.io, "cars/x", "xx")); try std.testing.expect(Rigg.have(&rig3.c2zz, "cars/x", "xx") and Rigg.have(&rig3.c3zz, "cars/x", "xx")); rig3.c1zz.deny = true; rig3.c1zz.stoo = false; try std.testing.expectError(error.CloudDeny, stoz.put(stoz.ctx2, aren, std.testing.io, "cars/y", "yy")); }
test "a delete that a mirror misses is queued and the drain removes the leftover" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); const stoz = mirr.fanzStor(&rig3.fanz); try stoz.put(stoz.ctx2, aren, std.testing.io, "cont/week-9.enc", "nine"); rig3.c3zz.stoo = true; try stoz.del2(stoz.ctx2, aren, std.testing.io, "cont/week-9.enc"); try std.testing.expect(!Rigg.have(&rig3.c1zz, "cont/week-9.enc", "nine") and !Rigg.have(&rig3.c2zz, "cont/week-9.enc", "nine")); try std.testing.expect(Rigg.have(&rig3.c3zz, "cont/week-9.enc", "nine")); rig3.c3zz.stoo = false; rig3.frsh(); const dres = try mirr.fanzDrai(&rig3.fanz, aren); try std.testing.expectEqual(@as(u32, 1), dres.done); try std.testing.expectEqual(@as(usize, 0), rig3.c3zz.map.count()); }
test "the monthly call budget pauses a mirror without failing it, a new month resumes" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); rig3.fanz.conf.clou_mirr_opsa_mont = 2; const stoz = mirr.fanzStor(&rig3.fanz); try stoz.put(stoz.ctx2, aren, std.testing.io, "cars/a", "a"); try stoz.put(stoz.ctx2, aren, std.testing.io, "cars/b", "b"); try stoz.put(stoz.ctx2, aren, std.testing.io, "cars/c", "c"); try std.testing.expect(rig3.stat.paus[1] and rig3.stat.paus[2]); try std.testing.expect(!rig3.stat.dead[1]); try std.testing.expect(!Rigg.have(&rig3.c3zz, "cars/c", "c")); try std.testing.expectEqual(@as(i64, 2), try quot.opsaGetz(&rig3.dbzz, "tigr", NOWZ)); try std.testing.expectEqual(@as(i64, 2), try mirr.fanzLeft(&rig3.fanz)); rig3.fanz.nowz = NOWZ + 40 * DAYZ; rig3.frsh(); const dres = try mirr.fanzDrai(&rig3.fanz, aren); try std.testing.expectEqual(@as(u32, 2), dres.done); try std.testing.expect(Rigg.have(&rig3.c3zz, "cars/c", "c")); }
test "weekly audit queues what a vendor lacks, counts orphans, finds a same-size corrupt copy, and drain repairs all" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); var stoz = rig3.c1zz.store(); try stoz.put(stoz.ctx2, aren, std.testing.io, "cars/rows.jsonl.gz", "rows-data"); try stoz.put(stoz.ctx2, aren, std.testing.io, "cont/latest.enc", "contact-blob"); try stoz.put(stoz.ctx2, aren, std.testing.io, "runs/20260101T000000Z-aa.pack", "packdata"); stoz = rig3.c2zz.store(); try stoz.put(stoz.ctx2, aren, std.testing.io, "cars/rows.jsonl.gz", "rows-data"); try stoz.put(stoz.ctx2, aren, std.testing.io, "runs/20250101T000000Z-zz.pack", "stray"); var insz = try rig3.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz,vfyz,vend) VALUES('h1','runs/20260101T000000Z-aa.pack',0,8,1,'b2zz');"); defer insz.fini(); _ = try insz.step(); const aud1 = try audt.fanzAudt(&rig3.fanz, aren); try std.testing.expect(aud1.ranz); try std.testing.expectEqual(@as(u32, 1), aud1.orph); try std.testing.expectEqual(@as(u32, 5), aud1.quer); try std.testing.expectEqual(@as(u32, 0), aud1.bads); const aud2 = try audt.fanzAudt(&rig3.fanz, aren); try std.testing.expect(!aud2.ranz); rig3.frsh(); const drn1 = try mirr.fanzDrai(&rig3.fanz, aren); try std.testing.expectEqual(@as(u32, 5), drn1.done); try std.testing.expect(Rigg.have(&rig3.c3zz, "runs/20260101T000000Z-aa.pack", "packdata") and Rigg.have(&rig3.c2zz, "cont/latest.enc", "contact-blob")); const keyz = rig3.c3zz.map.getPtr("cont/latest.enc").?; keyz.*[0] ^= 0x20; try fail.flagSetz(&rig3.dbzz, "mirr_audt", 1); rig3.fanz.nowz = NOWZ + 30 * DAYZ; rig3.frsh(); const aud3 = try audt.fanzAudt(&rig3.fanz, aren); try std.testing.expectEqual(@as(u32, 1), aud3.bads); rig3.frsh(); _ = try mirr.fanzDrai(&rig3.fanz, aren); try std.testing.expect(Rigg.have(&rig3.c3zz, "cont/latest.enc", "contact-blob")); }
